import { describe, expect, test } from "bun:test";
import { taskTitle } from "../apps/client/src/lib/projects/terminal-title.ts";

describe("taskTitle", () => {
	test("claude: topic without the spinner glyph", () => {
		expect(taskTitle("claude", "✳ Terminal blind overlay")).toBe("Terminal blind overlay");
		expect(taskTitle("claude", "⠂ Terminal blind overlay")).toBe("Terminal blind overlay");
		expect(taskTitle("claude", "✳ Claude Code")).toBeNull();
		expect(taskTitle("claude", "")).toBeNull();
	});
	test("pi: the session name between the app title and the folder", () => {
		expect(taskTitle("pi", "π - fix login - dashboard")).toBe("fix login");
		expect(taskTitle("pi", "Pi-Bolt - a - b - dashboard")).toBe("a - b");
		expect(taskTitle("pi", "π - dashboard")).toBeNull();
	});
});

