 * 터미널 창 제목에서 지금 일하는 주제(태스크)를 꺼내기.
 *
 * 에이전트마다 창 제목 형식이 다르다.
 * - `claude`: 앞의 스피너 글리프(`✳`, `⠂` 등) 뒤에 주제가 온다. `Claude Code` 는 주제 없는 기본 제목이라 null.
 * - `pi`: `{앱 제목} - {세션 이름} - {폴더}` 꼴이라, 세션 이름은 첫 ` - ` 와 마지막 ` - ` 사이만 남는다.
 *   부분(앱·폴더만)이 모자라면 null.
 */

/** Claude Code 기본 창 제목(주제가 없을 때). */
const CLAUDE_DEFAULT_TITLE = "Claude Code";

/** 스피너 글리프 한 글자 + 공백을 떼고 나머지를 돌려준다(없으면 그대로). */
function stripSpinner(title: string): string {
	// `✳ Terminal…` / `⠂ Terminal…` 처럼 비영숫자 기호 한 글자와 공백으로 시작하는 경우.
	const match = /^([^\p{L}\p{N}\s])\s+(.+)$/u.exec(title);
	return match ? match[2] : title;
}

/** 에이전트 창 제목에서 태스크 주제를 꺼낸다(없으면 null). */
export function taskTitle(agent: string, title: string | null | undefined): string | null {
	const text = title?.trim();
	if (!text) return null;

	switch (agent.trim().toLowerCase()) {
		case "claude": {
			const topic = stripSpinner(text).trim();
			if (!topic || topic === CLAUDE_DEFAULT_TITLE) return null;
			return topic;
		}
		case "pi": {
			const first = text.indexOf(" - ");
			const last = text.lastIndexOf(" - ");
			// 앱 제목과 폴더가 둘 다 있어야 세션 이름이 있다.
			if (first === -1 || last <= first) return null;
			const session = text.slice(first + 3, last).trim();
			return session ? session : null;
		}
		default:
			return null;
	}
}
